#include <bits/stdc++.h>
using namespace std;

typedef bitset<128> bs128;

const int MOD = 1000000007;
const int INV = 570000004;

inline int add_mod(int a, int b) {
    int s = a + b;
    return s >= MOD ? s - MOD : s;
}

inline int sub_mod(int a, int b) {
    int s = a - b;
    return s < 0 ? s + MOD : s;
}

inline int mul_mod(int a, int b) {
    return (int)((1LL * a * b) % MOD);
}

unordered_map<bs128, int> index_map;
int total_nodes, time_stamp, child[65536][128];

int dfs(bs128 state) {
    auto it = index_map.find(state);
    if (it != index_map.end()) return it->second;
    int id = time_stamp++;
    index_map[state] = id;
    for (int mask = 0; mask < (1 << total_nodes); ++mask) {
        bs128 new_state = state;
        for (int j = 0; j < (1 << total_nodes); ++j) {
            if (!new_state[j]) {
                for (int k = mask & j; k; k ^= k & -k) {
                    if (state[j ^ (k & -k)]) {
                        new_state[j] = 1;
                        break;
                    }
                }
            }
        }
        child[id][mask] = dfs(new_state);
    }
    return id;
}

int p[7][7], q[7][128], dp[8][65536];

int main() {
    int n;
    cin >> n;
    dfs(bs128(1));
    for (int i = 0; i < n; ++i) for (int j = 0; j < n; ++j) {
        cin >> p[i][j];
        p[i][j] = mul_mod(p[i][j], INV);
    }
    for (int i = 0; i < n; ++i) for (int j = 0; j < (1 << n); ++j) {
        q[i][j] = 1;
        for (int k = 0; k < n; ++k) {
            int val = (j >> k) & 1 ? p[k][i] : sub_mod(1, p[k][i]);
            q[i][j] = mul_mod(q[i][j], val);
        }
    }
    dp[0][0] = 1;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < time_stamp; ++j) {
            for (int k = 0; k < (1 << n); ++k) {
                int next_state = child[j][k];
                dp[i + 1][next_state] = add_mod(dp[i + 1][next_state], mul_mod(dp[i][j], q[i][k]));
            }
        }
    }
    bs128 result;
    for (int i = 0; i < (1 << n); ++i) result[i] = 1;
    cout << dp[n][index_map[result]] << endl;
}
